/*
 * Remote Servo Control
 *
 * Control a servo motor from your phone!
 * Use the A0 slider on the remote to
 * set the servo angle (0-180 degrees).
 *
 * How to use:
 * 1. Run this sketch
 * 2. Click the Remote button (phone icon)
 * 3. Open the URL on your phone
 * 4. Slide A0 to control servo angle
 */

#include <Servo.h>

Servo myServo;
int servoPin = 9;

void setup() {
  Serial.begin(9600);
  myServo.attach(servoPin);
  myServo.write(90);
  Serial.println("Servo ready!");
  Serial.println("Slide A0 to control angle.");
}

void loop() {
  int val = analogRead(A0);
  int angle = map(val, 0, 1023, 0, 180);
  myServo.write(angle);
  delay(50);
}
